// Step 1: run first. Returns the 10 nearest documents over all docs. The caller collects the `id` values into a list.
query nearest_docs($q: Vector(3)) {
    match { $d: Doc }
    return { $d.id }
    order { nearest($d.embedding, $q) }
    limit 10
}
```

```gq
// Step 2: the caller passes the step 1 ids as $ids and the collection slug as $coll. The result is the titles of the top-10 docs that belong to the collection.
query titles_in_collection($ids: [String], $coll: String) {
    match {
        $d: Doc
        $d.id in $ids
        $c: Collection { slug: $coll }
        $d "in" $c
    }
    return { $d.title }
}
